--

CREATE TABLE public.usuarios_vacante (
    id bigint NOT NULL,
    titulo character varying(200) NOT NULL,
    descripcion text NOT NULL,
    tipo_empleo character varying(20) NOT NULL,
    modalidad character varying(15) NOT NULL,
    salario_min numeric(10,2),
    salario_max numeric(10,2),
    detalles_salario character varying(200),
    fecha_inicio_estimada date,
    fecha_publicacion timestamp with time zone NOT NULL,
    fecha_limite date,
    fecha_actualizacion timestamp with time zone NOT NULL,
    estado_vacante character varying(15) NOT NULL,
    aprobada boolean NOT NULL,
    destacada boolean NOT NULL,
    max_postulantes integer NOT NULL,
    max_postulaciones_por_interesado integer NOT NULL,
    categoria_id bigint NOT NULL,
    reclutador_id bigint NOT NULL,
    secretaria_id bigint NOT NULL,
    municipio character varying(50) NOT NULL,
    max_postulaciones_por_consulta integer NOT NULL
);


